class Controller:
    def __init__(self):
        self._generation = 0
        self._rows = []
        self._decisions = {}
        self._busy = False
        self._pending_results = {}
    def start(self):
        self._generation += 1
        self._rows = []
        self._decisions = {}
        self._busy = True
        return self._generation
    def poll_status(self, generation, status):
        if generation != self._generation or status not in ['queued', 'running', 'failed', 'completed']:
            return False
        if status == 'completed' and generation == self._generation:
            if generation in self._pending_results:
                return True
            else:
                self._pending_results[generation] = True
                return True
        elif status in ['queued', 'running']:
            return False
        else:  # 'failed'
            self._busy = False
            return False
    def finish(self, generation, rows):
        if generation != self._generation or generation not in self._pending_results:
            return False
        self._rows = rows.copy()
        self._busy = False
        del self._pending_results[generation]
        return True
    def set_decision(self, job_id, value):
        self._decisions[job_id] = value
